import React from 'react';
import { notFound } from 'next/navigation';
import fs from 'fs';
import path from 'path';

// Bu sayfa SSR (Sunucu Tarafı Oluşturma) veya SSG ile SEO optimizasyonu sağlar.
export default async function ProductPage({ params }: { params: { slug: string } }) {
  const filePath = path.join(process.cwd(), 'src/data/elit-saatler.json');
  const fileContents = fs.readFileSync(filePath, 'utf8');
  const watches = JSON.parse(fileContents);
  
  const slug = (await params).slug;
  const watch = watches.find((w: any) => w.seoUrl === `/elit-saat/${slug}`);

  if (!watch) {
    notFound();
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20 text-foreground">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
        {/* Görsel Alanı */}
        <div className="bg-surface border border-surface-border p-8 flex items-center justify-center min-h-[500px]">
          <div className="text-surface-border text-8xl opacity-10 absolute font-serif italic">S</div>
          <div className="text-gray-400 text-sm z-10 text-center">
            [Görsel Alanı] <br/>
            <span className="text-xs text-primary">{watch.image}</span>
          </div>
        </div>

        {/* Ürün Detayları */}
        <div className="flex flex-col justify-center">
          <h2 className="text-primary tracking-[0.2em] uppercase text-sm font-bold mb-2">{watch.brand}</h2>
          <h1 className="text-3xl md:text-5xl font-bold mb-6">{watch.modelName}</h1>
          <p className="text-3xl font-light text-gray-300 mb-8">{watch.price}</p>
          
          <div className="space-y-4 mb-10">
            <div className="flex justify-between border-b border-surface-border pb-2">
              <span className="text-gray-400">Durum</span>
              <span className="text-white">{watch.condition}</span>
            </div>
            <div className="flex justify-between border-b border-surface-border pb-2">
              <span className="text-gray-400">Stok</span>
              <span className="text-white">{watch.stock > 0 ? 'Mevcut' : 'Tükendi'}</span>
            </div>
          </div>

          <button className="bg-primary hover:bg-primary-hover text-black font-bold uppercase tracking-widest py-4 w-full transition-colors">
            VIP Satın Al
          </button>
        </div>
      </div>
    </div>
  );
}
